  "basis/basis.wm": "// The expected-outcome exceptions of the Basis Library as one datatype. A Basis function that\n// raises one of these returns `Result<T, Basis.Error>` in Workman (`markdown/basis-design.md`,\n// Basis exceptions). `Overflow`, `Div` and `Size` panic instead and have no constructor here.\n// `Io` and `SysErr` join when the Basis IO structures do.\ntype Error =\n  | Empty\n  | Subscript\n  | Chr\n  | Domain\n  | Option\n  | UnequalLengths\n  | Unordered\n  | Fail<String>;\n",
  "basis/byte.wm": "from js.module(\"./js/byte_vector.js\") import unsafe {\n  bytesToString as primBytesToString: Word8Vector.Vector -> String,\n  stringToBytes as primStringToBytes: String -> Word8Vector.Vector\n};\n\nlet bytesToString = primBytesToString;\n\nlet stringToBytes = primStringToBytes;\n",
  "basis/float32.wm": "from js.module(\"./js/float.js\") import unsafe {\n  float32Round as primFromNumber: Number -> Float32.Real,\n  float32Round as primToNumber: Float32.Real -> Number,\n  float32Add: (Float32.Real, Float32.Real) -> Float32.Real,\n  float32Sub: (Float32.Real, Float32.Real) -> Float32.Real,\n  float32Mul: (Float32.Real, Float32.Real) -> Float32.Real,\n  float32Div: (Float32.Real, Float32.Real) -> Float32.Real,\n  float32Neg: Float32.Real -> Float32.Real\n};\n\nlet fromNumber = primFromNumber;\nlet toNumber = primToNumber;\nlet add = float32Add;\nlet sub = float32Sub;\nlet mul = float32Mul;\nlet div = float32Div;\nlet neg = float32Neg;\n",
