  "basis/general.wm": "// Basis `GENERAL`, without `exn`, the exceptions and `ref` (`markdown/core-design.md`). The\n// expected-outcome exceptions are `Basis.Error` constructors instead. `Order` is the spec's `order`,\n// capitalized (BD11).\ntype Order = Less | Equal | Greater;\n\n// Function composition: `o(f, g)` is `(x) => f(g(x))`.\nlet o = (f, g) => {\n  (value) => { f(g(value)) }\n};\n\n// Both arguments are evaluated, left first; the result is the first.\nlet before = (value, _: Void) => { value };\n\nlet ignore = (_) => { void };\n",
  "basis/list_pair.wm": "from \"./basis.wm\" import * as Basis;\n\n// Basis `LIST_PAIR`. The plain functions ignore the excess of the longer list; the `Eq` functions\n// return `Err(Basis.UnequalLengths)` instead. Arguments come data-first so pipes work, and fold\n// functions take `(a, b, accumulator)` as in the spec.\n\nlet rec zip = match(left, right) => {\n  ([a, ..restA], [b, ..restB]) => { [(a, b), ..zip(restA, restB)] },\n  (_, _) => { [] }\n};\n\nlet rec zipEq = match(left, right) => {\n  ([], []) => { Ok([]) },\n  ([a, ..restA], [b, ..restB]) => {\n    match(zipEq(restA, restB)) {\n      Ok(rest) => { Ok([(a, b), ..rest]) },\n      Err(error) => { Err(error) }\n    }\n  },\n  (_, _) => { Err(Basis.UnequalLengths) }\n};\n\nlet rec unzip = match(pairs) => {\n  [] => { ([], []) },\n  [pair, ..rest] => {\n    let (a, b) = pair;\n    let (lefts, rights) = unzip(rest);\n    ([a, ..lefts], [b, ..rights])\n  }\n};\n\nlet rec app = match(left, right, f) => {\n  ([a, ..restA], [b, ..restB], f) => {\n    f(a, b);\n    app(restA, restB, f)\n  },\n  (_, _, _) => { void }\n};\n\nlet rec appEq = match(left, right, f) => {\n  ([], [], _) => { Ok(void) },\n  ([a, ..restA], [b, ..restB], f) => {\n    f(a, b);\n    appEq(restA, restB, f)\n  },\n  (_, _, _) => { Err(Basis.UnequalLengths) }\n};\n\nlet rec map = match(left, right, f) => {\n  ([a, ..restA], [b, ..restB], f) => {\n    let head = f(a, b);\n    [head, ..map(restA, restB, f)]\n  },\n  (_, _, _) => { [] }\n};\n\nlet rec mapEq = match(left, right, f) => {\n  ([], [], _) => { Ok([]) },\n  ([a, ..restA], [b, ..restB], f) => {\n    let head = f(a, b);\n    match(mapEq(restA, restB, f)) {\n      Ok(rest) => { Ok([head, ..rest]) },\n      Err(error) => { Err(error) }\n    }\n  },\n  (_, _, _) => { Err(Basis.UnequalLengths) }\n};\n\nlet rec foldl = match(left, right, initial, f) => {\n  ([a, ..restA], [b, ..restB], initial, f) => { foldl(restA, restB, f(a, b, initial), f) },\n  (_, _, initial, _) => { initial }\n};\n\nlet rec foldr = match(left, right, initial, f) => {\n  ([a, ..restA], [b, ..restB], initial, f) => { f(a, b, foldr(restA, restB, initial, f)) },\n  (_, _, initial, _) => { initial }\n};\n\nlet rec foldlEq = match(left, right, initial, f) => {\n  ([], [], initial, _) => { Ok(initial) },\n  ([a, ..restA], [b, ..restB], initial, f) => { foldlEq(restA, restB, f(a, b, initial), f) },\n  (_, _, _, _) => { Err(Basis.UnequalLengths) }\n};\n\nlet rec all = match(left, right, predicate) => {\n  ([a, ..restA], [b, ..restB], predicate) => {\n    if (predicate(a, b)) { all(restA, restB, predicate) } else { false }\n  },\n  (_, _, _) => { true }\n};\n\nlet rec exists = match(left, right, predicate) => {\n  ([a, ..restA], [b, ..restB], predicate) => {\n    if (predicate(a, b)) { true } else { exists(restA, restB, predicate) }\n  },\n  (_, _, _) => { false }\n};\n\nlet rec allEq = match(left, right, predicate) => {\n  ([], [], _) => { true },\n  ([a, ..restA], [b, ..restB], predicate) => {\n    if (predicate(a, b)) { allEq(restA, restB, predicate) } else { false }\n  },\n  (_, _, _) => { false }\n};\n\nlet foldrEq = (left, right, initial, f) => {\n  if (allEq(left, right, (_, _) => { true })) {\n    Ok(foldr(left, right, initial, f))\n  } else {\n    Err(Basis.UnequalLengths)\n  }\n};\n",
  "basis/math.wm": "// Basis `MATH` over `Number`, the JavaScript double. Each function is the matching `Math` member:\n// out-of-domain arguments give NaN and never raise, as the spec says.\nfrom js.global(\"Math\") import unsafe {\n  PI: Number,\n  E: Number,\n  sqrt as primSqrt: Number -> Number,\n  sin as primSin: Number -> Number,\n  cos as primCos: Number -> Number,\n  tan as primTan: Number -> Number,\n  asin as primAsin: Number -> Number,\n  acos as primAcos: Number -> Number,\n  atan as primAtan: Number -> Number,\n  atan2 as primAtan2: (Number, Number) -> Number,\n  exp as primExp: Number -> Number,\n  pow as primPow: (Number, Number) -> Number,\n  log as primLog: Number -> Number,\n  log10 as primLog10: Number -> Number,\n  sinh as primSinh: Number -> Number,\n  cosh as primCosh: Number -> Number,\n  tanh as primTanh: Number -> Number\n};\n\nlet pi = PI;\nlet e = E;\nlet sqrt = primSqrt;\nlet sin = primSin;\nlet cos = primCos;\nlet tan = primTan;\nlet asin = primAsin;\nlet acos = primAcos;\nlet atan = primAtan;\nlet atan2 = primAtan2;\nlet exp = primExp;\nlet pow = primPow;\nlet ln = primLog;\nlet log10 = primLog10;\nlet sinh = primSinh;\nlet cosh = primCosh;\nlet tanh = primTanh;\n",
